CREATE TABLE session_directory(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,external_id TEXT NOT NULL UNIQUE,session_id TEXT NOT NULL,lifetime TEXT NOT NULL,runtime_endpoint TEXT NOT NULL CHECK(octet_length(runtime_endpoint) BETWEEN 1 AND 128),created_by TEXT NOT NULL,operation_id TEXT NOT NULL CHECK(octet_length(operation_id) BETWEEN 1 AND 256),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,created_by,operation_id),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,lifetime,session_id) REFERENCES session_lifetime_owners(organization_id,tenant_id,project_id,agent_uid,lifetime,session_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(organization_id,tenant_id,created_by) REFERENCES principals(organization_id,tenant_id,subject_id) DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE session_directory ENABLE ROW LEVEL SECURITY;
ALTER TABLE session_directory FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON session_directory USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
CREATE TRIGGER immutable_session_directory BEFORE UPDATE OR DELETE ON session_directory FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
CREATE TABLE access_counters(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,bucket TEXT NOT NULL CHECK(octet_length(bucket)<=256),window_start_ms BIGINT NOT NULL,count BIGINT NOT NULL CHECK(count>=0),PRIMARY KEY(organization_id,tenant_id,bucket),FOREIGN KEY(organization_id,tenant_id) REFERENCES tenants(organization_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE access_leases(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,operation_id TEXT NOT NULL CHECK(octet_length(operation_id) BETWEEN 1 AND 256),subject_id TEXT NOT NULL,revocation_epoch BIGINT NOT NULL CHECK(revocation_epoch>=0),class TEXT NOT NULL CHECK(class IN ('request','web_socket')),expires_at_ms BIGINT NOT NULL,PRIMARY KEY(organization_id,tenant_id,operation_id),FOREIGN KEY(organization_id,tenant_id,subject_id) REFERENCES principals(organization_id,tenant_id,subject_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX access_active ON access_leases(organization_id,tenant_id,expires_at_ms);
ALTER TABLE access_counters ENABLE ROW LEVEL SECURITY;
ALTER TABLE access_counters FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON access_counters USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true));
ALTER TABLE access_leases ENABLE ROW LEVEL SECURITY;
ALTER TABLE access_leases FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON access_leases USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true));
